command:
// Öffnet das Wildnisreise-Fenster.
//
// Auch für Spieler gedacht: sie sehen den Reisetag, den Mond, wie die Gruppe
// unterwegs ist und die Rollentafel — wer welche Rolle hat, was dafür
// gewürfelt wird und welche Boni und Mali darauf liegen. Der Tagesbericht
// bleibt beim SL. Das Makro kann also bedenkenlos auf die gemeinsame
// Hotbar gelegt werden.
//
// Dasselbe erreicht der Knopf „Wildnisreise" in der linken Werkzeugleiste.
const api = game.modules.get("toa-adventure-tracker")?.api;

if (!api) {
  ui.notifications.error("Das Modul 'Wildnisreise' ist nicht aktiv.");
} else {
  api.open();
}

// Ablauf eines Reisetags:
//   1. Jeder tragt sich in eine Rolle ein (oder der SL verteilt sie).
//   2. SL: \"Tag laufen lassen\" - wurfelt alle offenen Rollen und wertet aus.
//   3. Bericht vorlesen.
//   4. SL: \"Anwenden\" - Schaden und Erschopfung auf die Bogen.
//   5. SL: \"Tag abschliessen\" - protokollieren und einen Tag weiter.
//
// Nur SL:
//   api.setDay(12);                       // Reisetag direkt setzen
//   api.adjustDay(1);                     // einen Tag weiter
//   api.setPace(\"fast\");                  // langsam / normal / schnell
//   api.setMode(\"ship\");                  // foot / mount / canoe / ship
//   await api.resolveDay();               // Tag auswerten (schreibt nichts auf Bogen)
//   api.clearReport();                    // Auswertung verwerfen
//
// Lesen darf jeder:
//   api.getState();        // der komplette Zustand
//   api.getRoles();        // die effektive Rollenliste
//   api.partyActors();     // wer als reisend gilt
//   api.worstExhaustion(); // hochster Erschopfungsgrad in der Gruppe
//   api.moonFor(30);       // Mondphase eines beliebigen Tages
